function testerTitle(p){return p.id==='fun-studio-testing'&&lang==='vi'?'<span class="tester-title-line">Kiểm thử Website thương hiệu</span><span class="tester-title-line">&amp; Hệ thống vận hành</span>':E(p.name)}
// Presentation layer inspired by the supplied Stitch screens. Content stays in content.js.
function header(d){return `<header><div class="header-inner">${navLink('/','<span class="brandmark personal-logo"><img src="/assets/personal-logo.png" alt=""></span><span class="brand-copy">Thuy Diem<small>BUSINESS ANALYST</small></span>','brand')}<nav id="navigation">${d.nav.map((n,i)=>navLink(routes[i],E(n),route()===routes[i]?'active':'')).join('')}</nav><div class="header-actions"><div class="lang-switch"><button class="lang ${lang==='vi'?'active':''}" data-lang="vi" aria-pressed="${lang==='vi'}">VI</button><span>/</span><button class="lang ${lang==='en'?'active':''}" data-lang="en" aria-pressed="${lang==='en'}">EN</button></div><button class="btn header-cv" data-action="cv">${d.cv} ↗</button><button class="menu-toggle" aria-label="${lang==='vi'?'Mở menu':'Open menu'}" aria-expanded="false" aria-controls="navigation">☰</button></div></div></header>`}
function home(d){return `<main class="wrap"><section class="hero"><div><span class="eyebrow">BUSINESS ANALYSIS · MIS</span><h1 class="hero-name"><span>Nguyen Thi</span><span>Thuy Diem</span></h1><p class="hero-role">Business Analyst</p><p class="intro">${d.intro}</p><div class="buttons">${navLink('/projects',(lang==='vi'?'Xem dự án':'View projects')+' <span aria-hidden="true">→</span>','btn')}<button class="btn secondary" data-action="cv"><svg aria-hidden="true" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg>${d.cv}</button></div></div><figure class="portrait-block"><div class="portrait"><img src="/assets/portrait.png" alt="Nguyen Thi Thuy Diem" class="portrait-photo"></div><div class="portrait-top-label"><span aria-hidden="true">✧</span> ANALYTICAL THINKING</div><div class="portrait-bottom-label">BA · MIS GRADUATE</div></figure></section><section class="philosophy-wide"><div class="philosophy-side"><span class="philosophy-icon" aria-hidden="true">❞</span><span class="overline">${d.philosophy}</span><small>Analytical Mindset</small></div><div class="philosophy-copy"><blockquote>${d.quote}</blockquote>${lang==='vi'?'<p class="philosophy-translation" lang="en">“Every limit starts as an unverified assumption”</p>':''}</div></section><section class="section">${journeyDashboard(d)}${heading('CORE VALUES',d.values,'')}<div class="values">${d.valueTitles.map((x,i)=>`<article class="value"><span class="num">0${i+1}</span><span class="value-symbol" aria-hidden="true">${['◎','⇄','✓','✧'][i]}</span><h3>${x}</h3><p>${d.valueTexts[i]}</p></article>`).join('')}</div></section><section class="section">${heading('PORTFOLIO SPOTLIGHT',d.featured,'',navLink('/projects',d.all+' ↗','text-link'))}${featuredSelector(d)}</section><section class="section">${heading('CAREER ROADMAP',d.roadmap,'')}<div class="roadmap"><article class="road-card"><div class="road-number">01</div><span class="overline">${d.short}</span><h3>${d.shortRole}</h3><h4>${d.goalsLabel}</h4><ul class="road-goals">${d.goalItems.map(x=>`<li>${E(x)}</li>`).join('')}</ul><h4>${d.focusLabel}</h4>${tags(d.shortTags)}</article><article class="road-card"><div class="road-number">02</div><span class="overline">${d.long}</span><h3>${d.longRole}</h3><h4>${d.growthLabel}</h4><p>${d.longText}</p>${tags(d.longTags)}</article></div></section>${contact(d)}</main>`}
function featuredSelector(d){const selected=d.projects.filter(p=>p.category===(homeCategory===0?'work':'project'));return `<div class="filters">${d.experienceTypeEnglish.map((x,i)=>`<button class="filter ${homeCategory===i?'active':''}" data-home-category="${i}" aria-pressed="${homeCategory===i}">${x}</button>`).join('')}</div><p>${d.experienceTypeDescriptions[homeCategory]}</p><div class="experience-vertical-grid">${selected.map(p=>card(p,d)).join('')}</div>`}

function card(p,d){const vi=lang==='vi',fuji=p.id==='fuji-brd',seo=p.id==='nukeviet-seo';return `<article class="vertical-exp-card"><div class="vertical-cover">${seo?`<div class="brd-cover seo-cover"><span>NUKEVIET PORTAL</span><strong>SEO</strong><small>ANALYTICS · CONTENT · SEARCH INTENT</small></div>`:fuji?`<div class="brd-cover"><span>FUJI SHIRYO</span><strong>BRD</strong><small>BUSINESS REQUIREMENTS DOCUMENT</small></div>`:`<img src="${p.coverImage||p.image}" alt="${E(p.name)}" loading="lazy">`}<span class="vertical-category">${p.category==='project'?'PROJECT EXPERIENCE':'WORK EXPERIENCE'}</span><div class="vertical-date">${E(p.time)}<span>${seo?'On-page SEO':fuji?'BRD Development':p.id==='snap-ba'?'Odoo ERP':p.id==='photobooth-product'?'Photobooth':'Web Testing'}</span></div></div><div class="vertical-copy"><h3>${E(p.role)}</h3><h4>${testerTitle(p)}</h4><p class="vertical-company">${E(p.projectLabel||p.company)}</p><p class="vertical-desc">${E(p.desc)}</p>${tags(p.tags)}<div class="vertical-highlight">${seo?(vi?'<strong>01</strong> website · Google Analytics':'<strong>01</strong> website · Google Analytics'):fuji?(vi?'<strong>BRD</strong> Trực tiếp xây dựng tài liệu':'<strong>BRD</strong> Authored the document'):E(p.highlights||'')}</div><button class="btn vertical-cta" data-project="${p.id}">${vi?'Xem chi tiết dự án':'View project details'} <span>→</span></button></div></article>`}

function experience(d){return `<main class="wrap experience-page"><div class="page-intro"><span class="eyebrow">PROFESSIONAL EXPERIENCE</span><h1>Work Experience <em>— Project</em></h1><p>${lang==='vi'?'Hành trình làm việc, đóng góp và trải nghiệm phát triển sản phẩm.':'Work, contributions and product development experience.'}</p></div><div class="experience-explainer">${d.experienceHeading.map((x,i)=>`<div><span class="overline">0${i+1}</span><h3>${x}</h3><p>${d.experienceTypeDescriptions[i]}</p></div>`).join('')}</div><div class="page-content"><div class="filters">${d.filters.map((x,i)=>`<button class="filter ${filter===i?'active':''}" data-filter="${i}" aria-pressed="${filter===i}">${x}</button>`).join('')}</div><div class="experience-vertical-grid">${d.projects.filter(p=>filter===0||(filter===1?p.category==='work':p.category==='project')).map(p=>card(p,d)).join('')}</div></div>${contact(d)}</main>`}
function education(d){const vi=lang==='vi';const section=(n,en,title)=>`<div class="edu-heading"><span class="overline">${n}. ${en}</span><h2>${title}</h2></div>`;return `<main class="edu-v2"><section class="wrap edu-top"><span class="edu-pill">● &nbsp; ACADEMIC FOUNDATION & SKILLS</span><h1>${d.eduTitle}</h1><div class="edu-metrics">${(vi?[
['TỐT NGHIỆP GPA','3.4','/ 4.0','Bằng giỏi'],
['HỌC BỔNG XUẤT SẮC','02','','2022–2023 & 2023–2024'],
['CHỨNG CHỈ CHUYÊN MÔN','05+','Verified','IIBA Endorsed & Meta'],
['CHUYÊN NGÀNH CHÍNH','MIS','','Quản lý Thông tin Doanh nghiệp']
]:[
['GRADUATION GPA','3.4','/ 4.0','Bachelor’s Degree — Graduated with Distinction'],
['ACADEMIC SCHOLARSHIPS','02','','2022–2023 & 2023–2024'],
['PROFESSIONAL CERTIFICATIONS','05+','Verified','IIBA Endorsed & Meta'],
['MAJOR','MIS','','Information Management']
]).map((x,i)=>`<div class="edu-metric-item ${i===3?'edu-major-metric':''}"><span class="edu-metric-label">${x[0]}</span><div class="edu-metric-value"><strong>${x[1]}</strong>${x[2]?`<span>${x[2]}</span>`:''}</div><small>${x[3]}</small></div>`).join('')}</div></section><section class="edu-band"><div class="wrap">${section('01','ACADEMIC FOUNDATION',vi?'Học vấn & Thành tựu học thuật':'Academic Background & Achievements')}<div class="edu-academic"><article class="edu-card edu-school"><div class="edu-card-top"><span class="badge">${vi?'CỬ NHÂN':'BACHELOR’S DEGREE'}</span><span>VNU-HN</span></div><h3>${d.school}</h3>${vi?'<p>University of Social Sciences and Humanities (VNU-HN)</p>':''}<div class="edu-degree"><span class="overline">${vi?'Chuyên ngành đào tạo':'Degree & Major'}</span><h4>${d.major}</h4></div><div class="edu-courses"><span class="overline">${d.courses}</span>${tags(d.courseItems)}</div></article><div class="edu-academic-side"><article class="edu-gpa"><span class="overline">ACADEMIC PERFORMANCE</span><div><strong>3.4</strong><span>/ 4.0 GPA</span></div><span class="edu-gpa-note">MANAGEMENT INFORMATION SYSTEMS</span></article><article class="edu-card edu-scholar"><span class="overline">✦ &nbsp; ${d.scholar}</span><h3>${d.scholarText}</h3>${['2022 – 2023','2023 – 2024'].map(y=>`<div class="edu-scholar-year"><span>${vi?'Năm học':'Academic year'} ${y}</span><span>✦</span></div>`).join('')}</article></div></div></div></section><section class="wrap edu-section">${section('02','CERTIFICATIONS',d.cert)}<div class="edu-certs">${d.certifications.map((c,i)=>`<article class="edu-card edu-cert"><div class="edu-card-top"><span class="edu-year">${c.year}</span><span>${i<3?'IIBA Endorsed':i===3?'Python & Quarto':'Meta & Mindstone'}</span></div><h3>${E(c.title)}</h3><p>${E(c.issuer||'')}</p><div class="edu-cert-foot"><span>${['AGILE BA','STRATEGIC BUSINESS ANALYSIS','BUSINESS PROCESS MAPPING','DATA REPORTING','GENERATIVE AI'][i]}</span><span aria-hidden="true">✧</span></div></article>`).join('')}</div></section><section class="edu-band"><div class="wrap">${section('03','CORE CAPABILITIES',vi?'Khung năng lực chuyên môn':'Core Capabilities')}<div class="edu-capabilities">${d.skillGroups.map((g,i)=>`<article class="edu-card edu-skill"><div class="edu-skill-title"><span aria-hidden="true">${['⊞','▤','◇','◎'][i]}</span><div><small>${vi?'NHÓM':'GROUP'} 0${i+1}</small><h3>${E(g.title)}</h3></div></div><span class="overline">${vi?'Kỹ năng chuyên môn':'Professional Skills'}</span>${tags(g.items)}</article>`).join('')}</div></div></section><section class="wrap edu-section">${section('04','THE BA TOOLBOX',d.tools)}<div class="edu-tools">${d.toolGroups.map((g,i)=>`<article class="edu-card"><div class="edu-tool-head"><h3>${g}</h3><span>${d.toolsLists[i].length} tools</span></div><div class="edu-tool-rows">${d.toolsLists[i].map((tool,j)=>`<div><span class="edu-tool-mark">${E(tool.substring(0,3).toUpperCase())}</span><strong>${E(tool)}</strong><small>${[['Backlog & Sprint Tracking','Kanban Workflow','ERP Configuration'],['Wireframes & Prototypes','Flowcharts','Process Modeling','Diagrams','Collaboration'],['Queries','Visual Dashboards','Spreadsheets']][i][j]||''}</small></div>`).join('')}</div></article>`).join('')}</div><div class="next-section"><div><span class="overline">NEXT STEP</span><h2>${vi?'Khám phá kinh nghiệm thực tế':'Explore my experience'}</h2></div>${navLink('/projects',d.nav[2]+' ↗','btn')}</div></section></main>`}
function personal(d){const vi=lang==='vi';return `<main class="wrap personal-page"><div class="page-intro"><span class="badge">PORTFOLIO · FEATURED CASE</span><h1>${d.personalTitle}</h1>${vi?`<p>${d.personalSub}</p>`:''}</div><article class="rootmap-feature"><a class="rootmap-visual" href="${d.personalUrl}" target="_blank" rel="noopener noreferrer" aria-label="Rootmap"><div class="browser-bar"><span>● ● ●</span><small>⌑ rootmapproject.vercel.app</small><span>↗</span></div><img src="/assets/rootmap-cover.png" alt="Rootmap — ${vi?'giao diện website':'website preview'}"><span class="visual-caption">${vi?'Giao diện ROOTMAP · Xem website ↗':'ROOTMAP preview · Visit website ↗'}</span></a><div class="rootmap-copy"><span class="badge">PERSONAL PROJECT · WEB / APP CONCEPT</span><h2>ROOTMAP</h2>${vi?'<h3>Cộng đồng du lịch bản địa</h3><blockquote>“Hiểu một vùng đất để mỗi hành trình trở nên ý nghĩa hơn.”</blockquote>':'<h3>A Community for Local Travel</h3><blockquote>“Discover a place deeply, and make every journey more meaningful.”</blockquote>'}<p>${d.personalDesc}</p><span class="overline">${vi?'Nhóm người dùng mục tiêu':'TARGET USERS'}</span><div class="target-users">${[['◎','Traveler',vi?'Người yêu du lịch, khám phá và chia sẻ trải nghiệm.':''],['✎','Local Guide / Travel Creator',vi?'Hướng dẫn viên và người sáng tạo nội dung du lịch.':''],['⌂','Local Partner',vi?'Homestay, làng nghề, nghệ nhân và các đơn vị địa phương.':'']].map(a=>`<div><span>${a[0]}</span><div><strong>${a[1]}</strong>${a[2]?`<p>${a[2]}</p>`:''}</div></div>`).join('')}</div><a href="${d.personalUrl}" target="_blank" rel="noopener noreferrer" class="btn">${vi?'Khám phá Rootmap':d.visit} ↗</a>${vi?'<p class="note">Xem đầy đủ ý tưởng và nội dung dự án trên website riêng.</p>':''}</div></article>${vi?`<section class="section">${heading('PRODUCT FRAMEWORK','Định hướng giải pháp & Tính năng cốt lõi','Định hướng sản phẩm trong giai đoạn nghiên cứu và phát triển concept.')}<div class="values">${[['◎','DISCOVERY','Khám phá bản địa','Tìm hiểu điểm đến, văn hóa và trải nghiệm địa phương.'],['♧','COMMUNITY','Kết nối cộng đồng','Chia sẻ review, câu chuyện, hình ảnh và hành trình.'],['⌁','PLANNING','Lập kế hoạch','Xây dựng lịch trình theo sở thích, thời gian và ngân sách.'],['⇄','ECOSYSTEM','Kết nối địa phương','Tìm hiểu dịch vụ và kết nối với Local Partner.']].map((a,i)=>`<article class="value"><span class="value-symbol">${a[0]}</span><span class="overline">0${i+1} / ${a[1]}</span><h3>${a[2]}</h3><p>${a[3]}</p></article>`).join('')}</div></section>`:`<section class="section">${heading('PRODUCT FRAMEWORK','Product Vision & Core Features','Product direction during the research and concept development phase.')}<div class="values">${[['◎','DISCOVERY','Explore Local Culture','Discover destinations, local culture, and authentic experiences.'],['♧','COMMUNITY','Connect with the Community','Share reviews, stories, photos, and travel experiences.'],['⌁','PLANNING','Plan Your Trip','Build itineraries based on your interests, schedule, and budget.'],['⇄','ECOSYSTEM','Connect with Local Partners','Explore local services and connect with local partners.']].map((a,i)=>`<article class="value"><span class="value-symbol">${a[0]}</span><span class="overline">0${i+1} / ${a[1]}</span><h3>${a[2]}</h3><p>${a[3]}</p></article>`).join('')}</div></section>`}</main>`}
function detailHero(p,d,vi){return `<div class="detail-breadcrumb"><button data-action="list">← ${vi?'Quay lại Kinh nghiệm':'Back to Experience'}</button><span>WORK EXPERIENCE / CASE STUDY</span></div><div class="detail-hero"><div><span class="badge">${E(p.role.toUpperCase())} · ${E(p.time)}</span><h2>${p.id==='photobooth-product'?E(p.name):testerTitle(p)}</h2><p>${E(p.desc)}</p>${tags(p.tags)}</div><aside><span class="overline">${vi?'Thông tin dự án':'PROJECT INFORMATION'}</span><dl><dt>${vi?'Doanh nghiệp':'Company'}</dt><dd>${E(p.company)}</dd><dt>${vi?'Vai trò':'Role'}</dt><dd>${E(p.detailRole||p.role)}</dd><dt>${vi?'Thời gian':'Period'}</dt><dd>${E(p.time)}</dd></dl></aside></div>`}
function projectDetails(p,d){if(p.id==='fuji-brd'||p.id==='nukeviet-seo'){fujiDetails(p,d);return}if(p.id==='snap-ba'){baDetails(p,d);return}if(p.id==='photobooth-product'){photoboothDetails(p,d);return}const vi=lang==='vi';const modules=vi?['Doanh thu','Lịch sử giao dịch','Nhượng quyền','Nhân sự','Quản lý lỗi','Voucher']:['Revenue','Transaction History','Franchise Management','Human Resources','Issue Management','Voucher Management'];const tasks=p.sections[1].items;openModal(`<div class="detail-page">${detailHero(p,d,vi)}<div class="tester-scope-cards">${(vi?[
['NỀN TẢNG','2 nền tảng Web','Website thương hiệu & Hệ thống vận hành'],
['QUY MÔ ĐỘI NGŨ','13 thành viên','1 PM, 1 PO, 6 Developer, 2 Tester, 2 BA, 1 Designer'],
['PHẠM VI HỆ THỐNG','6 nhóm chức năng','Doanh thu, lịch sử giao dịch, nhượng quyền, nhân sự, lỗi, voucher'],
['NHÓM NGƯỜI DÙNG','2 nhóm người dùng','Đối tác nhượng quyền (B2B) & Khách hàng chụp ảnh (B2C)']
]:[
['PLATFORMS','2 Web Platforms','Brand Public Portal & Operations Franchise Web'],
['TEAM SCALE','13-Member Team','1 PM, 1 PO, 6 Devs, 2 Testers, 2 BAs, 1 Designer'],
['SYSTEM SCOPE','6 Functional Areas','Revenue, Transactions, Franchise, HR, Issues, Vouchers'],
['USER GROUPS','2 User Groups','Franchise Partners (B2B) & Studio Customers (B2C)']
]).map((x,i)=>`<article><div class="scope-label"><span>${x[0]}</span><span aria-hidden="true">${['▣','♧','☑','♧'][i]}</span></div><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div><div class="detail-inner"><section class="detail-section">${heading('01 / PROJECT SCALE',vi?'Quy mô dự án & Đội ngũ':'Project Scale & Team','')}<div class="scale-box"><p>${E(p.facts[0])}</p><p>${E(p.facts[1])}</p></div></section><section class="detail-section">${heading('02 / PROJECT DESCRIPTION',p.sections[0].title,'')}<blockquote class="context-quote">${E(p.sections[0].text)}</blockquote><div class="platform-grid"><article><span class="badge">PUBLIC WEBSITE</span><h3>${vi?'Website thương hiệu Fun Studio':'Fun Studio Brand Website'}</h3><p>${vi?'Giới thiệu dịch vụ chụp ảnh, cửa hàng và cơ hội nhượng quyền.':'Photography services, store locations and franchise opportunities.'}</p>${tags(['B2B · Franchise Partners','B2C · Photography Customers'])}</article><article><span class="badge">INTERNAL OPERATIONS</span><h3>${vi?'Hệ thống vận hành nội bộ':'Internal Operations System'}</h3><div class="module-grid">${modules.map((x,i)=>`<div><span>0${i+1}</span>${x}</div>`).join('')}</div></article></div><button class="tester-image" data-zoom="${p.image}"><img src="${p.image}" alt="Fun Studio — ${vi?'hệ thống cửa hàng':'store locations'}"><span>${d.zoom} ↗</span></button></section><section class="detail-section">${heading('03 / KEY TASKS',p.sections[1].title,'')}<div class="task-grid">${tasks.map((x,i)=>`<article><span class="badge">0${i+1} / ${['UI/UX TESTING','CONTENT & NAVIGATION','WEBSITE SECTIONS','FUNCTIONAL TESTING'][i]}</span><p>${E(x)}</p></article>`).join('')}</div></section><section class="detail-section">${heading('04 / KEY ACHIEVEMENTS',vi?'Kết quả đạt được':'Key Achievements','')}<div class="tester-results">${p.achievements.map(x=>`<article><strong>${x[0]}</strong><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div></section><div class="detail-end"><button class="btn secondary" data-action="list">← ${d.back}</button><button class="btn" data-project="photobooth-product">Photobooth Web App ↗</button></div></div></div>`)}
function photoboothDetails(p,d){const vi=lang==='vi',items=p.sections[1].items;const groups=vi?['Nghiên cứu & Định hướng sản phẩm','Phát triển tính năng & Trải nghiệm','Phối hợp & Theo dõi triển khai']:['Research & Product Direction','Features & Experiences','Coordination & Delivery Support'];openModal(`<div class="detail-page">${detailHero(p,d,vi)}<div class="tester-scope-cards pm-scope-cards">${(vi?[
['NỀN TẢNG','2 nền tảng','Photobooth App · Merchandise Web App'],
['QUY MÔ ĐỘI NGŨ','14 thành viên','1 PM, 1 PO, 6 Developer, 2 Tester, 2 BA, 2 Designer'],
['PHẠM VI SẢN PHẨM','3 nhóm tính năng','Chỉnh sửa ảnh & khuôn mặt · Bộ lọc màu · Cá nhân hóa merchandise'],
['TRẢI NGHIỆM','Concept Photobooth','Kết hợp thiết bị chụp ảnh, không gian thực tế và trải nghiệm số']
]:[
['PLATFORMS','2 platforms','Photobooth App · Merchandise Web App'],
['TEAM SCALE','14-member team','1 PM, 1 PO, 6 Developers, 2 Testers, 2 BAs, 2 Designers'],
['PRODUCT SCOPE','3 feature areas','Photo & facial editing · Color filters · Merchandise personalization'],
['EXPERIENCE','Photobooth concepts','Photo equipment, physical setups and digital experiences']
]).map((x,i)=>`<article><div class="scope-label"><span>${x[0]}</span><span aria-hidden="true">${['▣','♧','☑','♧'][i]}</span></div><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div><div class="detail-inner"><section class="detail-section">${heading(vi?'01 / QUY MÔ DỰ ÁN':'01 / PROJECT SCALE',vi?'Quy mô dự án & Đội ngũ':'Project Scale & Team','')}<div class="scale-box">${p.facts.map(x=>`<p>${E(x)}</p>`).join('')}</div></section><section class="detail-section">${heading(vi?'02 / MÔ TẢ SẢN PHẨM':'02 / PRODUCT DESCRIPTION',p.sections[0].title,'')}<blockquote class="context-quote">${E(p.sections[0].text)}</blockquote></section><section class="detail-section">${heading(vi?'03 / ĐÓNG GÓP':'03 / CONTRIBUTIONS',p.sections[1].title,'')}<div class="pm-contribution-grid">${items.map((item,i)=>`<article><div class="pm-contribution-meta"><span>0${i+1} / ${['R&D','PM SUPPORT','STAKEHOLDER','OPERATIONS','FEATURE DEV','CREATIVE','E-COMMERCE','CONCEPT'][i]}</span><span aria-hidden="true">${['◎','▤','◇','▣','◉','✧','⊞','▧'][i]}</span></div><h3>${E(p.contributionTitles[i])}</h3><p>${E(item)}</p><span class="pm-contribution-tag">${['MARKET RESEARCH','PRODUCT ROADMAP','REQUIREMENT ALIGNMENT','RESOURCE ASSESSMENT','FACE RETOUCHING','RETRO & Y2K','WEB CUSTOMIZATION','PHYSICAL & DIGITAL'][i]}</span></article>`).join('')}</div><div class="photobooth-gallery">${p.images.map((src,i)=>`<button class="case-cover-button" data-zoom="${src}" aria-label="${E(d.zoom)}"><img src="${src}" alt="${i===0?'Photobooth merchandise':'Photobooth concepts'}"><span>${i===0?(vi?'Sản phẩm cá nhân hóa':'Merchandise'):(vi?'3 tính năng filter':'3 Filter Features')} · ${d.zoom} ↗</span></button>`).join('')}</div></section><section class="detail-section">${heading(vi?'04 / KẾT QUẢ':'04 / KEY ACHIEVEMENTS',p.sections[2].title,'')}<div class="pm-outcomes">${p.sections[2].items.map((x,i)=>`<article><span class="overline">0${i+1} / ${vi?'KẾT QUẢ':'OUTCOME'}</span><p>${E(x)}</p></article>`).join('')}</div></section><div class="detail-end"><button class="btn secondary" data-action="list">← ${d.back}</button><button class="btn" data-project="fun-studio-testing">Tester Intern ↗</button></div></div></div>`)}
render();

function baDetails(p,d){
 const vi=lang==='vi';

 const overview=vi?[['NỀN TẢNG','4 nền tảng','Odoo ERP · Warehouse Scanning · Đặt sân · Sự kiện'],['QUY MÔ ĐỘI NGŨ','12 thành viên','1 PM · 3 BA · 8 Developer'],['PHẠM VI ODOO','2 phân hệ','CRM/Sales · Kho'],['VAI TRÒ','Business Analyst','Phân tích yêu cầu · Đặc tả · Mockup · UAT']]:[['PLATFORMS','4 platforms','Odoo ERP · 3 web applications'],['TEAM SIZE','12 members','1 PM · 3 BAs · 8 Developers'],['ODOO SCOPE','2 modules','CRM/Sales · Warehouse'],['ROLE','Business Analyst','Requirements · Specifications · Mockups · UAT']];
 openModal(`<div class="detail-page ba-detail">${detailHero(p,d,vi)}<div class="tester-scope-cards">${overview.map(x=>`<article><div class="scope-label">${E(x[0])}</div><h3>${E(x[1])}</h3><p>${E(x[2])}</p></article>`).join('')}</div><div class="detail-inner">
 <section class="detail-section">${heading('01 / PROJECT SCALE',(vi?'Quy mô dự án':'Project Scope'),'')}<div class="scale-box"><p><strong>${vi?"Lĩnh vực:":"Domains:"}</strong> ${E(p.domain)}</p><p><strong>${vi?"Quy mô nhóm:":"Team Size:"}</strong> ${E(p.team)}</p></div><div class="ba-platform-grid">${p.scope.map((x,i)=>`<article><span class="overline">0${i+1} / PLATFORM</span><h3>${E(x[0])}</h3><p>${E(x[1])}</p></article>`).join('')}</div></section>
 <section class="detail-section">${heading('02 / PROJECT DESCRIPTION',(vi?'Mô tả dự án':'Project Description'),'')}<p class="ba-description-intro">${E(p.contributionIntro)}</p><div class="ba-description-list">${p.descriptions.map((x,i)=>`<article><span class="ba-index">0${i+1}</span><div><h3>${E(x[0])}</h3><p>${E(x[1])}</p></div></article>`).join('')}</div></section>
 <section class="detail-section ba-contributions">${heading('03 / CONTRIBUTIONS',(vi?'Công việc & Đóng góp của Business Analyst':'Key Responsibilities & Contributions'),'')}<div class="ba-pillar-grid">${p.workGroups.map((g,i)=>`<article class="ba-pillar"><header><span class="ba-letter">${i?'B':'A'}</span><div><h3>${vi?(i?'Khối 3 Ứng Dụng Web':'Khối Odoo ERP'):E(g.title)}</h3><span class="ba-micro">${vi?(i?'Phân tích yêu cầu, thiết kế & hỗ trợ triển khai':'Phân tích nghiệp vụ & đặc tả hệ thống'):(i?'Requirements, Design & Implementation Support':'Business Analysis & System Specifications')}</span></div><span class="ba-pillar-badge">${i?'WEB PRODUCTS':'CORE SYSTEMS'}</span></header><ol>${g.items.map((x,j)=>`<li><span class="ba-task-no">0${j+1}.</span><div><h4>${E(p.workTitles[i][j])}</h4><p>${E(x)}</p></div></li>`).join('')}</ol></article>`).join('')}</div></section>
 <section class="detail-section">${heading('04 / DELIVERABLES',(vi?'Kết quả & Đầu ra':'Key Achievements & Deliverables'),'')}<div class="ba-deliverable-grid">
 <article><header><span>${vi?"CẤU TRÚC HỒ SƠ ĐẶC TẢ":"ODOO DOCUMENTATION"}</span><strong>10 Docs</strong></header><div class="ba-doc-row"><span aria-hidden="true">▤</span><div><h4>${vi?"08 Tài liệu Đặc tả Nghiệp vụ (SRS)":"08 Specifications"}</h4><p>${vi?"Quy định chi tiết luồng dữ liệu, bảng dữ liệu, phân quyền và màn hình Odoo.":"Functional specifications for CRM/Sales and Warehouse."}</p></div></div><div class="ba-doc-row"><span aria-hidden="true">♧</span><div><h4>02 Change Requests (CR)</h4><p>${vi?"Phân tích tác động mở rộng quy trình đóng gói Package và quản lý phụ thu.":"Change Requests for Odoo."}</p></div></div></article>
 <article><header><span>${vi?"PHÂN RÃ USER STORIES":"USER STORY BREAKDOWN"}</span><strong>184 Stories</strong></header><div class="ba-matrix"><div><span>CRM & Sales Module</span><b>104 Stories</b></div><div><span>${vi?"Inventory / Kho Module":"Warehouse Module"}</span><b>73 Stories</b></div><div><span>${vi?"CR Đóng thùng (Package)":"Packaging Change Request"}</span><b>07 Stories</b></div></div></article>
 <article><header><span>${vi?"MA TRẬN TEST PHÂN VAI":"ROLE-BASED TESTING"}</span><strong>${vi?"06 Nhóm":"06 Groups"}</strong></header><div class="ba-matrix"><div><span>CRM / Sales Test Groups</span><b>${vi?"3 Nhóm Vai Trò":"3 Testing Groups"}</b></div><div><span>${vi?"Kho / Logistics Test Groups":"Warehouse Test Groups"}</span><b>${vi?"3 Nhóm Vai Trò":"3 Testing Groups"}</b></div><div class="ba-matrix-highlight"><span>Web Scanner + 2 Web</span><b>${vi?"100% Mockup & SOP":"Mockups \u00b7 Tests \u00b7 User Guides"}</b></div></div></article>
 </div>${!vi?`<ul class="ba-output-summary">${p.deliverableSummary.map(x=>`<li>${E(x)}</li>`).join('')}</ul>`:''}</section>
 <section class="detail-section ba-figma-section">${heading('05 / FIGMA',(vi?'Thiết kế giao diện':'Interface Designs'),'')}<div class="ba-figma-grid">${p.figmaLinks.map((x,i)=>`<a class="ba-figma-card" href="${E(x.url)}" target="_blank" rel="noopener noreferrer"><span class="ba-figma-icon" aria-hidden="true">${figmaMark()}</span><div><span class="ba-figma-tag">FIGMA · 0${i+1}</span><h3>${E(x.title)}</h3><p>${vi?"Xem thiết kế trên Figma":"View designs on Figma"}</p></div><span class="ba-figma-arrow" aria-hidden="true">↗</span></a>`).join('')}</div></section>
 <div class="detail-end"><button class="btn secondary" data-action="list">← ${d.back}</button><button class="btn" data-project="photobooth-product">Product Management Assistant ↗</button></div></div></div>`);
}

function figmaMark(){return '<svg viewBox="0 0 38 56" width="26" height="38" fill="none"><path d="M10 56a9 9 0 0 0 9-9v-9h-9a9 9 0 1 0 0 18Z" fill="#0ACF83"/><path d="M1 28a9 9 0 0 1 9-9h9v19h-9a9 9 0 0 1-9-10Z" fill="#A259FF"/><circle cx="28" cy="28" r="9" fill="#1ABCFE"/><path d="M1 10a9 9 0 0 1 9-9h9v18h-9a9 9 0 0 1-9-9Z" fill="#F24E1E"/><path d="M19 1h9a9 9 0 1 1 0 18h-9V1Z" fill="#FF7262"/></svg>'}

function fujiDetails(p,d){const vi=lang==='vi',seo=p.id==='nukeviet-seo';openModal(`<div class="detail-page fuji-detail"><div class="detail-breadcrumb"><button data-action="list">← ${d.back}</button><span>PROJECT EXPERIENCE / CASE STUDY</span></div><div class="detail-hero"><div><span class="badge">${E(p.role.toUpperCase())} · ${p.time}</span><h2>${E(p.name)}</h2><p>${E(p.desc)}</p>${tags(p.tags)}</div><aside><span class="overline">${vi?'Thông tin dự án':'PROJECT INFORMATION'}</span><dl>${[[vi?'Vai trò':'Role',p.role],[vi?'Dự án':'Project',seo?p.name:p.projectLabel],[vi?'Thời gian':'Period',p.time],[vi?'Lĩnh vực':'Domain',p.domain],[seo?(vi?'Nền tảng':'Platform'):(vi?'Quy mô nhóm':'Team Size'),seo?p.platform:p.team]].filter((x,i)=>!seo||i!==0).map(x=>`<dt>${x[0]}</dt><dd>${E(x[1])}</dd>`).join('')}</dl></aside></div><div class="detail-inner"><section class="detail-section"><div class="scale-box"><strong>${vi?'Quy mô dự án':'Project Scope'}</strong><p>${E(p.scope)}</p></div></section><section class="detail-section">${heading('01 / DISCOVERY',p.sections[0].title,'')}<blockquote class="context-quote">${E(p.sections[0].text)}</blockquote></section><section class="detail-section">${heading('02 / CONTRIBUTIONS',p.sections[1].title,'')}<div class="fuji-task-grid">${p.sections[1].items.map((x,i)=>`<article class="${!seo&&i===4?'fuji-brd-task':''}"><span class="overline">0${i+1}</span><p>${!seo&&i===4?'<strong>'+E(x)+'</strong>':E(x)}</p></article>`).join('')}</div></section><section class="detail-section">${heading('03 / DELIVERABLES',p.sections[2].title,'')}<div class="fuji-results">${p.sections[2].items.map((x,i)=>`<article><span class="badge">${(seo?['ANALYTICS','ON-PAGE SEO','SEO CONTENT']:['BRD',vi?'YÊU CẦU HỆ THỐNG':'SYSTEM REQUIREMENTS','PRD INPUT'])[i]}</span><p>${E(x)}</p></article>`).join('')}</div></section><div class="detail-end"><button class="btn secondary" data-action="list">← ${d.back}</button></div></div></div>`)}
